--初始化页签信息
function BattleSelectionDialog:InitData()
    self._allVo = {}
    local t = CfUtils.GetCfTable(AutoIds.IdSetting1602)
    if IsNull(t) then
        return
    end

    for k, v in pairs(t) do
        local vo = ActionTypeVo.New()
        vo:FillVo(v)
        if not self._allVo[checkString(vo.tab)] then
            self._allVo[checkString(vo.tab)] = {}
        end
        table.insert(self._allVo[checkString(vo.tab)], vo)
    end  

    for k, v in pairs(self._allVo) do
        table.sort(v, function(a, b)
            return checkNumber(a.order) < checkNumber(b.order)
        end) 
        if table.count(v) > 1 then
            for i = 1, table.count(v) do
                for j = i + 1, table.count(v) do
                    local fd = v[i]
                    local td = v[j]
                    if GameUtils.IsUnlockedBySystemTogId(checkNumber(td.id)) and not GameUtils.IsUnlockedBySystemTogId(checkNumber(fd.id)) then
                        local d = fd
                        v[j] = d
                        v[i] = td
                    end
                end
            end
        end
    end
end

function BattleSelectionDialog:FillToggles()
    for k, v in pairs(ActionType) do
        local go = self.CommonTopLabelGroup.transform:Find("Button"..v.type)
        self:FillToggle(go, v)
    end

    local go = self.CommonTopLabelGroup.transform:Find("Button"..checkNumber(self._curTogType))
    if go then
        local tog = go.transform:GetComponent(typeof(Toggle))
        tog.isOn = true
    end
end

function BattleSelectionDialog:FillToggle(go, data)
    if not go or not data then
        return
    end
    
    local tog = go.transform:GetComponent(typeof(Toggle))
    tog.isOn = false
    tog.onValueChanged:RemoveAllListeners()
    tog.onValueChanged:AddListener(function(value)
        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_supply_change)
        KTool.SetActive(go.transform:Find("Item2"), value)
        KTool.SetActive(go.transform:Find("Item1"), not value)
        if value then
            self:ReferseType(data.type)
        end
        CfUtils.SetUISwitchText(go.transform:Find("Text"), value and 2 or 1)
    end)
    KTool.SetActive(go, true)
end

function BattleSelectionDialog:ReferseType(type)
    type = checkNumber(type)
    if not self._allVo or type < 1 then
        return
    end
    self._listVos = self._allVo[checkString(type)]
    if not self._listVos then
        return
    end

    self._curTogType = type
    CS.Engine.Lib.KCookie.Set("BattleSelectionTogType", type)

    if not self._isInitList then
        self.LoopList:InitListView(table.count(self._listVos), Bind(self, self.OnRefreshIndex))
        self._isInitList = true
    else
        GameUtils.ReloadData(self.LoopList, table.count(self._listVos))
    end
    self.LoopList:MovePanelToItemIndex(self:GetIndex())
end

function BattleSelectionDialog:OnRefreshIndex(listView, index)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("Cell")
    local data = self._listVos[index + 1]

    local scr = CfUtils.GetLuaScr(cell, BattleSelectionTogNode)
    if scr then
        local actionData = self:GetActionInfoById(data.id)
        scr:Refresh(data, actionData, function(value)
            local vo = data
            if not vo then
                return
            end

            local questType = 0
            if checkNumber(vo.id) == Constants.SystemToggleIds.Id3 then        --日常
                xRecord.record('3-002')
                GameUtils.Request(Interfaces.DailyQuest, {}, function(request, response)
                    if checkInt(response.errCode) == 0 then
                        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
                        comp:Initial(response.data)
                        CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UIFightMap, parameters = {}}, {
                            { id = Constants.UITypeIds.BattleSelection }
                        })
                    end
                end)
                questType = Constants.IDType.QuestCoinsCopy
            elseif checkNumber(vo.id) == Constants.SystemToggleIds.Id10 then   --装备
                CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UIFastReliefDisasterResponseDialog, parameters = {}}, {
                    { id = Constants.UITypeIds.BattleSelection }
                })
                xRecord.record('3-003')
                questType = Constants.IDType.QuestPrimaryEquipCopy
            --elseif checkNumber(vo.id) == Constants.SystemToggleIds.Id29 then   --木桩
            --    CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.TrainFieldChooseModeDialog, parameters = {}}, {
            --        { id = Constants.UITypeIds.BattleSelection }
            --    })
            --    questType = Constants.IDType.QuestTrainField
            elseif checkNumber(vo.id) == Constants.SystemToggleIds.Id8 then    --迷宫
                local MazeMgr = import('Game.Maze.MazeMgr')
                MazeMgr:GetInstance():EnterMaze({{id = Constants.UITypeIds.BattleSelection}})
                questType = Constants.IDType.QuestMaze
                xRecord.record('3-005')
            elseif checkNumber(vo.id) == Constants.SystemToggleIds.Id14 then   --世界boss
                local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
                worldBossComponent:OnWorldBossEnter()
                questType = Constants.IDType.QuestWorldBoss
                xRecord.record('3-009')
            elseif checkNumber(vo.id) == Constants.SystemToggleIds.Id11 then   --假想实战
                UIModule.OpenDialog({id = Constants.UITypeIds.UIGachaCoinQuestDialog},
                    {{id = Constants.UITypeIds.BattleSelection}}
                )
                xRecord.record('3-006')
                questType = Constants.IDType.QuestGachaCoin
            elseif checkNumber(vo.id) == Constants.SystemToggleIds.Id20 then   --定向作战
                GameUtils.ShowBlackOverlay()
                UIModule.OpenDialog({id = Constants.UITypeIds.DirectionalDialog},
                        {{id = Constants.UITypeIds.BattleSelection}}
                )
                questType = Constants.IDType.QuestDirectionalFight
            elseif checkNumber(vo.id) == Constants.SystemToggleIds.Id15 then   --爬塔
                local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
                local isOpen = towerQuestComponent:IsOpen()
                if not isOpen then
                    GameUtils.Toast(localize("未开启"))
                    return 
                end
                xRecord.record('3-008')
                CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UIClimbTowerMainDialog, parameters = {}}, {
                    { id = Constants.UITypeIds.BattleSelection }
                })
                questType = Constants.IDType.QuestTower
            elseif checkNumber(vo.id) == Constants.SystemToggleIds.Id9 then    --风暴挑战
                local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                local trialRemainTime = checkInt(playerComponent.playerDojo.trialRemainTime)
                if trialRemainTime <= Constants.MIN_TRIAL_CAN_ENTER then
                    GameUtils.Toast(localize('试炼未开始'))
                    return
                end
                xRecord.record('3-007')
                questType = Constants.IDType.QuestTrail
                UIModule.OpenDialog({ id = Constants.UITypeIds.TrailStageMain }, { { id = Constants.UITypeIds.BattleSelection } })
            elseif checkNumber(vo.id) == Constants.SystemToggleIds.Id22 then    --天赋
                CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UITalentMaterialDialog, parameters = {}}, {
                    { id = Constants.UITypeIds.BattleSelection }
                })
            elseif checkNumber(vo.id) == Constants.SystemToggleIds.Id16 then --- 风暴巅峰
                ---@type PVPArenaUtils
                local PVPArenaUtils = import('Game.Utils.PVPArenaUtils')
                local excludeDialogs = {
                    { id = Constants.UITypeIds.BattleSelection },
                }
                PVPArenaUtils.ShowMainDialog(excludeDialogs, true)
            else
                GameUtils.Toast(localize("暂未开放"))
            end

            CS.Engine.Lib.KCookie.Set(Constants.UICacheDataKeys.UIBattleSelectionChooseType, checkNumber(questType))
        end)
    end
    return cell
end

--获取当前下标
function BattleSelectionDialog:GetIndex(systemId)
    if checkNumber(systemId) == 0 then
        if self._curType == Constants.IDType.QuestCoinsCopy or self._curType == Constants.IDType.QuestExpCopy or self._curType == Constants.IDType.QuestUpStarCopy then
            systemId = Constants.SystemToggleIds.Id3
        elseif self._curType == Constants.IDType.QuestMaze then
            systemId = Constants.SystemToggleIds.Id8
        elseif self._curType == Constants.IDType.QuestTrail then
            systemId = Constants.SystemToggleIds.Id9
        elseif self._curType == Constants.IDType.QuestGachaCoin or self._curType == Constants.IDType.QuestGachaCoinChallenge then
            systemId = Constants.SystemToggleIds.Id11
        elseif self._curType == Constants.IDType.QuestPrimaryEquipCopy or self._curType == Constants.IDType.QuestSeniorEquipCopy then
            systemId = Constants.SystemToggleIds.Id10
        elseif self._curType == Constants.IDType.QuestTower then
            systemId = Constants.SystemToggleIds.Id15
        elseif self._curType == Constants.IDType.QuestWorldBoss then
            systemId = Constants.SystemToggleIds.Id14
        elseif self._curType == Constants.IDType.QuestTalent then
            systemId = Constants.SystemToggleIds.Id22
        elseif self._curType == Constants.IDType.QuestTrainField then
            systemId = Constants.SystemToggleIds.Id29
        end
    end

    local index = 0 
    for k, _t in pairs(self._allVo) do
        for _, v in pairs(_t) do
            if checkNumber(v.id) == checkNumber(systemId) then
                index = k
                break
            end
        end
    end
    return index - 1
end

--开启倒计时
function BattleSelectionDialog:StartTimeDown()
    if not self._allData then
        return
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        for k, v in pairs(self._allData) do
            if isTable(v) then
                if checkNumber(k) == Constants.SystemToggleIds.Id14 then
                    local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
                    if worldBossComponent:IsOpen() then
                        self:SetTipsList(checkNumber(k))
                    else
                        self:RemoveTipsList(checkNumber(k))
                    end
                    --[[
                    v.worldBossStartTime = checkNumber(v.worldBossStartTime) - 1
                    if v.worldBossStartTime <= 0 then
                        local vo = CfUtils.GetCfVo(AutoIds.IdSetting1602, "ActionTypeVo", checkNumber(k))
                        if vo then
                            v.worldBossStartTime = checkNumber(vo.duration)
                        end
                    end
                    ]]
                elseif checkNumber(k) == Constants.SystemToggleIds.Id3 then
                    if checkNumber(v.closeTime) > 0 then
                        v.closeTime = checkNumber(v.closeTime) - 1
                    end
                elseif checkNumber(k) == Constants.SystemToggleIds.Id8 then
                    v.mazeRemainTime = checkNumber(v.mazeRemainTime) - 1
                    if v.mazeRemainTime <= 0 then
                        local vo = CfUtils.GetCfVo(AutoIds.IdSetting1602, "ActionTypeVo", checkNumber(k))
                        if vo then
                            v.mazeRemainTime = checkNumber(vo.duration)
                        end
                    end
                elseif checkNumber(k) == Constants.SystemToggleIds.Id22 then
                    if checkNumber(v.closeTime) > 0 then
                        v.closeTime = checkNumber(v.closeTime) - 1
                    end
                elseif checkNumber(k) == Constants.SystemToggleIds.Id20 then
                    if checkNumber(v.questRemainTime) > 0 then
                        v.questRemainTime = checkNumber(v.questRemainTime) - 1
                        self:SetTipsList(checkNumber(k))
                    else
                        self:RemoveTipsList(checkNumber(k))
                    end
                elseif checkNumber(k) == Constants.SystemToggleIds.Id16 then
                    v.nextStageLeftSeconds = checkNumber(v.nextStageLeftSeconds - 1)
                    if checkNumber(v.nextStageLeftSeconds) <= 0 then
                        ---@type PVPArenaComponent
                        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
                        self._allData[k] = comp:GetPVPArenaEntryDojo()
                    end
                end
            end
        end
        if self._tipsTime % 4 == 0 then 
            self:RefreshTipsInfo()
        end
        self._tipsTime = self._tipsTime + 1

        Events.Broadcast(Constants.EventNames.ActionTimeDown, {})
    end, CountDownTime, false, true)
end

function BattleSelectionDialog:RefreshTipsInfo()
    if not self._tipsList then
        return
    end

    if table.count(self._tipsList) <= 0 then
        KTool.SetActive(self.TxtState2, false)
    else
        local ind = (self._tipsTime / 4) % table.count(self._tipsList) + 1
        local vo =  CfUtils.GetCfVo(AutoIds.IdSetting1602, "ActionTypeVo", checkNumber(self._tipsList[ind]))
        if vo then
            KTool.SetActive(self.TxtState2, true)
            CfUtils.FillText(self.TxtState2, vo.tipsTxt)
        end
    end
end

function BattleSelectionDialog:SetTipsList(systemToggleId)
    if not self._tipsList then
        return
    end
    local key = table.keyof(self._tipsList, checkNumber(systemToggleId))
    if not key then
        table.insert(self._tipsList, systemToggleId)
    end
end

function BattleSelectionDialog:RemoveTipsList(systemToggleId)
    if not self._tipsList then
        return
    end
    local key = table.keyof(self._tipsList, checkNumber(systemToggleId))
    if key then
        table.remove(key)
    end
end

---GetActionInfoById  获取单个行动的信息
---@param SystemToggleId number 系统功能id
function BattleSelectionDialog:GetActionInfoById(systemToggleId)
    if checkNumber(systemToggleId) == 0 then
        return nil
    end
    return self._allData[checkString(systemToggleId)] 
end

function BattleSelectionDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
        CriWareUtils.PlayMusicById("bgm_action")

        CfUtils.SetTopCommonActive(true, false)
        CfUtils.RefreshTopGoods({Constants.Currency.FreeDiamondId, Constants.Currency.HpId})

        local isInit = false
        GameUtils.Request(Interfaces.PlayerActionHome, {}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
            end
    
            local jsonData = response.data
            local actionInfo = jsonData.actionInfo
            if actionInfo then
                for k, v in pairs(actionInfo) do
                    self._allData[checkString(k)] = v 
                    if checkNumber(k) == Constants.SystemToggleIds.Id15 then   --爬塔
                        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
                        comp:Initial(v)
                    elseif checkNumber(k) == Constants.SystemToggleIds.Id14 then
                        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
                        comp:InitialBossInfo(v)
                    elseif checkNumber(k) == Constants.SystemToggleIds.Id22 then
                        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
                        comp:InitActiveInfo(v)
                    elseif checkNumber(k) == Constants.SystemToggleIds.Id16 then
                        ---@type PVPArenaComponent
                        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
                        comp:InitEntry(v)
                    end
                end
            end

            local args = self.controller.Argument.parameters
            --是道具跳转过来
            if not isNull(args) then
                self._curType = checkNumber(args.curTab)
            else
                self._curType = CS.Engine.Lib.KCookie.Get(Constants.UICacheDataKeys.UIBattleSelectionChooseType)
            end
        
            if not self._curType then
                self._curType = Constants.IDType.QuestCoinsCopy
            end
        
            --副本的其他类型处理一下
            if self._curType == Constants.IDType.QuestExpCopy or self._curType == Constants.IDType.QuestUpStarCopy then
                self._curType = Constants.IDType.QuestCoinsCopy
            --抽卡挑战副本处理
            elseif self._curType == Constants.IDType.QuestGachaCoinChallenge then
                self._curType = Constants.IDType.QuestGachaCoin
            --装备副本处理
            elseif self._curType == Constants.IDType.QuestSeniorEquipCopy then
                self._curType = Constants.IDType.QuestPrimaryEquipCopy
            end

            self._curTogType = CS.Engine.Lib.KCookie.Get("BattleSelectionTogType")
            if checkNumber(self._curTogType) == 0 then
                self._curTogType = 1
            end

            self:InitData()
            self:FillToggles()
            self:StartTimeDown()
        end)
    end))
    return coWait
end

function BattleSelectionDialog:OnEVENT_GUIDE_CUSTOM_UI_BEHAVIOR(body)
    if not body then
        return
    end

    self.LoopList:MovePanelToItemIndex(self:GetIndex(body.systemId))
end

function BattleSelectionDialog:RemoveTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

function BattleSelectionDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.EVENT_GUIDE_CUSTOM_UI_BEHAVIOR, self.EventEVENT_GUIDE_CUSTOM_UI_BEHAVIOR)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.TrailQuest)
        self:RemoveTimeDown()
        self.controller = nil
        --luabehaviour 中CSharp对象
        self:Delete()
        self = nil
    end))
    return coWait
end

return BattleSelectionDialog